func handler(req map[string]interface{}) map[string]interface{} {
	// Demonstrate environment-based configuration
	config := map[string]interface{}{
		"app": map[string]string{
			"name":    EnvOr("APP_NAME", "default-app"),
			"version": EnvOr("APP_VERSION", "0.0.0"),
			"region":  EnvOr("APP_REGION", "local"),
		},
		"features": map[string]bool{
			"dark_mode": Env("FEATURE_DARK_MODE") == "true",
			"beta_api":  Env("FEATURE_BETA_API") == "true",
		},
		"limits": map[string]string{
			"max_retries": EnvOr("MAX_RETRIES", "5"),
		},
	}

	Log("config loaded for", EnvOr("APP_NAME", "unknown"))

	return map[string]interface{}{
		"config":    config,
		"loaded_at": time.Now().UTC().Format(time.RFC3339),
	}
}
